package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.*;
import androidx.test.uiautomator.*;
import org.junit.Test;
import java.io.File;
import java.lang.reflect.Field;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.Assert.*;

/** Isolated saved records and owned calendar windows; no sensor, scheduler or output action. */
public class RecordCalendarFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice ui=UiDevice.getInstance(i);
    private Object field(Object owner,String name){try{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    private <T extends Activity>T resumed(Class<T> type){Activity[] found={null};i.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(type.isInstance(a))found[0]=a;});return type.cast(found[0]);}
    private <T extends Activity>T await(Class<T> type,Activity old){long until=SystemClock.elapsedRealtime()+7000;T a;while((a=resumed(type))==null||a==old){assertTrue("Expected a distinct resumed "+type.getSimpleName(),SystemClock.elapsedRealtime()<until);SystemClock.sleep(50);}return a;}
    private <T extends Activity>T recreate(T old,Class<T> type){i.runOnMainSync(old::recreate);T next=await(type,old);long until=SystemClock.elapsedRealtime()+5000;while(!old.isDestroyed()){assertTrue("Previous owner must be destroyed",SystemClock.elapsedRealtime()<until);SystemClock.sleep(50);}return next;}
    private void clickText(String value){UiObject2 view=ui.wait(Until.findObject(By.text(value)),5000);assertNotNull(value,view);view.click();ui.waitForIdle();}
    private void clickDesc(String value){UiObject2 view=ui.wait(Until.findObject(By.desc(value)),5000);assertNotNull(value,view);view.click();ui.waitForIdle();}
    private void pending(LocalDate date){assertTrue("Pending selection must be explicit",ui.wait(Until.hasObject(By.desc("Choose date "+date).selected(true)),5000));assertTrue(ui.hasObject(By.desc("Pending date "+date)));}
    private void capture(String name,Activity owner,boolean calendar)throws Exception{CountDownLatch frame=new CountDownLatch(1);boolean[] registered={false};long until=SystemClock.elapsedRealtime()+6000;while(!registered[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{Object holder=owner;if(owner instanceof RecordEditorActivity)holder=field(owner,"timeEditor");if(holder==null)return;Object window=calendar?field(holder,"calendar"):holder;if(window==null)return;Dialog dialog=(Dialog)field(window,"dialog");View decor=dialog.getWindow().getDecorView();if(!dialog.isShowing()||!decor.hasWindowFocus()||!decor.isAttachedToWindow()||decor.getWidth()<=0||decor.getHeight()<=0)return;assertTrue(decor.isHardwareAccelerated());decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();registered[0]=true;});if(!registered[0])SystemClock.sleep(50);}assertTrue("Focused owned dialog must render",registered[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));ui.waitForIdle();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(ui.takeScreenshot(new File(folder,"calendar-"+name+".png")));}
    private String json(String database,long id){try(Store s=new Store(c,database)){RecordEntry r=Records.get(s,id);return r.edit.start+":"+r.edit.end+":"+r.updated;}}
    private android.widget.TextView text(View view,String expected){if(view instanceof android.widget.TextView label&&expected.contentEquals(label.getText()))return label;if(view instanceof android.view.ViewGroup group)for(int n=0;n<group.getChildCount();n++){android.widget.TextView found=text(group.getChildAt(n),expected);if(found!=null)return found;}return null;}
    private void dateAction(Activity owner,String label){long until=SystemClock.elapsedRealtime()+5000;android.graphics.Rect hit=new android.graphics.Rect();boolean[] ready={false};while(!ready[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{Object holder=owner instanceof RecordEditorActivity?field(owner,"timeEditor"):owner;if(holder==null)return;Object calendar=field(holder,"calendar");if(calendar==null)return;Dialog dialog=(Dialog)field(calendar,"dialog");View decor=dialog.getWindow().getDecorView();if(!dialog.isShowing()||!decor.hasWindowFocus())return;android.widget.TextView action=text(decor,label);if(action!=null&&action.isEnabled()&&action.getGlobalVisibleRect(hit)&&hit.width()>0&&hit.height()>0){int[] screen=new int[2];action.getLocationOnScreen(screen);hit.set(screen[0],screen[1],screen[0]+action.getWidth(),screen[1]+action.getHeight());ready[0]=true;}});if(!ready[0])SystemClock.sleep(50);}assertTrue("Focused owned calendar must expose "+label,ready[0]);assertTrue("Tap owned calendar "+label,ui.click(hit.centerX(),hit.centerY()));ui.waitForIdle();}
    private void outerDate(RecordEditorActivity owner,String expected){long until=SystemClock.elapsedRealtime()+5000;boolean[] ready={false};while(!ready[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{Object editor=field(owner,"timeEditor");if(editor==null)return;Dialog dialog=(Dialog)field(editor,"dialog");android.widget.TextView date=(android.widget.TextView)field(editor,"dateButton");ready[0]=dialog.isShowing()&&dialog.getWindow().getDecorView().hasWindowFocus()&&date.isShown()&&expected.contentEquals(date.getText());});if(!ready[0])SystemClock.sleep(50);}assertTrue("Focused outer time form must show "+expected,ready[0]);}
    @Test public void pendingCalendarsRecreateCancelAndCommitWithoutChangingOffsetsOrSeconds()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",ui.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));assertFalse(AlarmService.active);
        String database="sleepwell-calendar-"+UUID.randomUUID()+".db";Records.Factory prior=Records.factory;Map<String,?> prefs=new HashMap<>(Prefs.of(c).getAll());List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){owned.add(a);assertFalse(a instanceof AlarmActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(callbacks);
        try{
            Records.factory=context->new Store(context,database);LocalDate today=LocalDate.now(),day=today.minusDays(2);long foldId;ZoneId berlin=ZoneId.of("Europe/Berlin");LocalDateTime fold=LocalDateTime.parse("2025-10-26T02:30:17.321");long exact=RecordDraft.instant(fold,berlin,ZoneOffset.ofHours(1));try(Store s=new Store(c,database)){long end=day.atTime(7,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();Records.create(s,new RecordDraft(end-8*3600000L,end),ZoneId.systemDefault(),System.currentTimeMillis());foldId=Records.create(s,new RecordDraft(exact,exact+60000),berlin,System.currentTimeMillis());}String original=json(database,foldId);
            c.startActivity(new Intent(c,HistoryActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","ISOLATED CALENDAR FIXTURE").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));HistoryActivity history=await(HistoryActivity.class,null);assertTrue(ui.wait(Until.hasObject(By.desc("Filter by date")),5000));clickDesc("Filter by date");if(!YearMonth.from(day).equals(YearMonth.from(today)))clickDesc("Previous month");clickDesc("Choose date "+day);pending(day);capture("history",history,true);history=recreate(history,HistoryActivity.class);pending(day);capture("history-recreated",history,true);clickText("Cancel");assertTrue(ui.wait(Until.gone(By.text("Records ending on")),5000));assertFalse("Cancel cannot apply the pending date filter",ui.hasObject(By.textContains("Recorded and user-reported periods.")));
            clickDesc("Filter by date");if(!YearMonth.from(day).equals(YearMonth.from(today)))clickDesc("Previous month");clickDesc("Choose date "+day);clickText("Use date");assertTrue(ui.wait(Until.gone(By.text("Records ending on")),5000));assertTrue(ui.wait(Until.hasObject(By.textContains("Recorded and user-reported periods.")),5000));clickDesc("Filter by date");pending(day);clickDesc("All dates");assertTrue(ui.wait(Until.gone(By.text("Records ending on")),5000));clickDesc("Trends");clickDesc("Trend options");clickText("Choose dates");clickDesc("Choose date "+day);pending(day);capture("trend",history,true);clickText("Cancel");assertTrue(ui.wait(Until.gone(By.text("Trend date")),5000));
            c.startActivity(new Intent(c,RecordEditorActivity.class).putExtra("record",foldId).putExtra("visualReview",true).putExtra("verificationLabel","ISOLATED DST/SECONDS FIXTURE").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
            RecordEditorActivity editor=await(RecordEditorActivity.class,null);
            clickDesc("Change start time");
            assertTrue("Original repeated-hour later offset must remain available",ui.wait(Until.hasObject(By.text("Later offset · UTC+01:00")),5000));
            assertEquals("17",ui.findObject(By.desc("Seconds")).getText());
            clickDesc("Choose start date");clickDesc("Choose date 2025-10-25");pending(LocalDate.parse("2025-10-25"));capture("editor",editor,true);
            editor=recreate(editor,RecordEditorActivity.class);
            pending(LocalDate.parse("2025-10-25"));capture("editor-recreated",editor,true);
            dateAction(editor,"Cancel");
            assertTrue("Cancel must dismiss the nested date window",ui.wait(Until.gone(By.text("Start date")),5000));
            outerDate(editor,"Sun 26 Oct 2025");
            assertEquals("Cancel must preserve exact pending seconds","17",ui.findObject(By.desc("Seconds")).getText());
            clickDesc("Choose start date");clickDesc("Choose date 2025-10-25");dateAction(editor,"Use date");
            assertTrue("Use date must dismiss the nested date window",ui.wait(Until.gone(By.text("Start date")),5000));
            outerDate(editor,"Sat 25 Oct 2025");capture("editor-selected",editor,false);
            assertEquals("Date selection is still an unsaved time-form draft",original,json(database,foldId));
            clickText("Cancel");assertTrue("Cancel must dismiss the outer time form",ui.wait(Until.gone(By.text("Use time")),5000));assertEquals(original,json(database,foldId));
            clickDesc("Change start time");clickText("Use time");assertTrue(ui.wait(Until.gone(By.text("Use time")),5000));clickText("Save changes");long end=SystemClock.elapsedRealtime()+7000;while(!editor.isDestroyed()){assertTrue("Save must finish",SystemClock.elapsedRealtime()<end);SystemClock.sleep(50);}try(Store s=new Store(c,database)){assertEquals("Unchanged later-fold instant keeps milliseconds",exact,Records.get(s,foldId).edit.start);assertEquals(exact+60000,Records.get(s,foldId).edit.end);}
            c.startActivity(new Intent(c,RecordEditorActivity.class).putExtra("record",foldId).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));editor=await(RecordEditorActivity.class,null);clickDesc("Change start time");assertTrue(ui.wait(Until.hasObject(By.text("Later offset · UTC+01:00")),5000));assertEquals("17",ui.findObject(By.desc("Seconds")).getText());clickDesc("Choose start date");clickDesc("Choose date 2025-10-25");dateAction(editor,"Use date");assertTrue(ui.wait(Until.gone(By.text("Start date")),5000));clickText("Use time");assertTrue(ui.wait(Until.gone(By.text("Use time")),5000));clickText("Save changes");end=SystemClock.elapsedRealtime()+7000;while(!editor.isDestroyed()){assertTrue("Changed date save must finish",SystemClock.elapsedRealtime()<end);SystemClock.sleep(50);}try(Store s=new Store(c,database)){assertEquals("Changing the date resolves its own offset and preserves seconds/milliseconds",RecordDraft.instant(fold.minusDays(1),berlin,ZoneOffset.ofHours(2)),Records.get(s,foldId).edit.start);assertEquals(exact+60000,Records.get(s,foldId).edit.end);}c.startActivity(new Intent(c,RecordEditorActivity.class).putExtra("record",foldId).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));editor=await(RecordEditorActivity.class,null);clickDesc("Change start time");clickDesc("Choose start date");pending(LocalDate.parse("2025-10-25"));capture("reopened",editor,true);dateAction(editor,"Cancel");assertTrue(ui.wait(Until.gone(By.text("Start date")),5000));clickText("Cancel");assertTrue(ui.wait(Until.gone(By.text("Use time")),5000));assertEquals(prefs,Prefs.of(c).getAll());assertFalse(TrackingService.running);assertFalse(AlarmService.active);
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());ui.takeScreenshot(new File(folder,"calendar-failure.png"));ui.dumpWindowHierarchy(new File(folder,"calendar-failure.xml"));}catch(Exception|AssertionError diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});long end=SystemClock.elapsedRealtime()+10000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<end){i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});SystemClock.sleep(50);}assertTrue("All isolated screen owners must close before restoring storage",owned.stream().allMatch(Activity::isDestroyed));for(Activity a:owned){if(a instanceof HistoryActivity)((HistoryActivity)a).awaitReaders(5000);if(a instanceof RecordEditorActivity)((RecordEditorActivity)a).awaitReaders(5000);}}finally{app.unregisterActivityLifecycleCallbacks(callbacks);Records.factory=prior;if(owned.stream().allMatch(Activity::isDestroyed))c.deleteDatabase(database);assertEquals(prefs,Prefs.of(c).getAll());}}
    }
}
